this.sethost = function() {
    try {
        var currentHost = getConfig.call(this).host || getHosts()[0];
        var currentIndex = getHosts().indexOf(currentHost);
        var newIndex = (currentIndex + 1) % getHosts().length;
        var newHost = getHosts()[newIndex];
        setConfig.call(this, 'host', newHost);
        java.toast("\n已切换到：\n" + newHost + "\n刷新发现页生效");
    } catch(e) {
        setConfig.call(this, 'host', getHosts()[0]);
        java.toast("\n已初始化：" + getHosts()[0]);
    }
};

this.checkhost = function() {
    try {
        var currentHost = getServerHost();
        java.toast("\n当前服务器：\n" + currentHost);
    } catch(e) {
        java.toast("获取失败");
    }
};
